nst PAGES = [ 'wiki' => ['Wiki & Guides', 'https://github.com/bobthecow/psysh/wiki'], 'config' => ['Configuration', 'https://github.com/bobthecow/psysh/wiki/Configuration'], 'commands' => ['Built-in Commands', 'https://github.com/bobthecow/psysh/wiki/Commands'], 'github' => ['GitHub Repository', 'https://github.com/bobthecow/psysh'], ]; protected function configure(): void { $this ->setName('docs') ->setDescription('Documentation & guides') ->addArgument('page', InputArgument::OPTIONAL, 'Page to open: '.implode(', ', \array_keys(self::PAGES))); } protected function execute(InputInterface $input, OutputInterface $output): int { $page = $input->getArgument('page'); if ($page !== null) { if (!isset(self::PAGES[$page])) { $output->writeln(''); $output->writeln(\sprintf( '<error>Unknown page "%s". Available: %s</error>', $page, \implode(', ', \array_keys(self::PAGES)), )); $output->writeln(''); return 1; } [$label, $url] = self::PAGES[$page]; $output->writeln(''); $output->writeln(\sprintf('Opening <comment>%s</comment>: <href=%s>%s</>', $label, $url, $url)); $output->writeln(''); @\fwrite(\STDERR, "\033]7324;{$url}\007"); @\fflush(\STDERR); return 0; } $output->writeln(''); $output->writeln('<comment>Documentation:</comment>'); $output->writeln(''); foreach (self::PAGES as $key => [$label, $url]) { $output->writeln(\sprintf('  <info>docs %s</info>', $key)); $output->writeln(\sprintf('  %s — <href=%s>%s</>', $label, $url, $url)); $output->writeln(''); } $output->writeln('Tip: use <info>doc</info> to look up PHP documentation inline. Try <return>doc array_map</return>'); $output->writeln(''); return 0; } } } namespace Psy\Web { use Psy\Command\Command; use Symfony\Component\Console\Helper\Table; use Symfony\Component\Console\Helper\TableStyle; use Symfony\Component\Console\Input\InputInterface; use Symfony\Component\Console\Output\OutputInterface; class AboutCommand extends Command { private static function humanNumber(int $n): string { if ($n >= 1_000_000_000) { return \